1	// Stub for node:net — not available in CF Workers.
2	export class Socket { on() { return this; } connect() { return this; } end() { return this; } }
3	export class Server { on() { return this; } listen() { return this; } }
4	export function createServer() { return new Server(); }
5	export function createConnection() { return new Socket(); }
6	export function connect() { return new Socket(); }
7	
8	const IPV4_RE = /^(\d{1,3}\.){3}\d{1,3}$/;
9	const IPV6_RE = /^[\da-f:]+$/i;
10	export function isIP(input: string): 0 | 4 | 6 {
11	  if (IPV4_RE.test(input)) return 4;
12	  if (IPV6_RE.test(input) && input.includes(":")) return 6;
13	  return 0;
14	}
15	export function isIPv4(input: string): boolean { return isIP(input) === 4; }
16	export function isIPv6(input: string): boolean { return isIP(input) === 6; }
17	
18	export default { Socket, Server, createServer, createConnection, connect, isIP, isIPv4, isIPv6 };
